package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Defense_Command_Delivery_Api {
  def id: Art.BridgeId
  def defense_in_Id : Art.PortId
  def defense_out_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var defense_out: Mining_Threat_Retreat_Supervisor.Defense_Command.Type = $

  def put_defense_out(value : Mining_Threat_Retreat_Supervisor.Defense_Command.Type) : Unit = {
    Contract(
      Modifies(defense_out),
      Ensures(
        defense_out == value
      )
    )
    Spec {
      defense_out = value
    }

    Art.putValue(defense_out_Id, Mining_Threat_Retreat_Supervisor.Defense_Command_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Defense_Command_Delivery_Initialization_Api (
  val id: Art.BridgeId,
  val defense_in_Id : Art.PortId,
  val defense_out_Id : Art.PortId) extends Defense_Command_Delivery_Api

@datatype class Defense_Command_Delivery_Operational_Api (
  val id: Art.BridgeId,
  val defense_in_Id : Art.PortId,
  val defense_out_Id : Art.PortId) extends Defense_Command_Delivery_Api {

  // Logika spec var representing port state for incoming data port
  @spec var defense_in: Mining_Threat_Retreat_Supervisor.Defense_Command.Type = $

  def get_defense_in() : Option[Mining_Threat_Retreat_Supervisor.Defense_Command.Type] = {
    Contract(
      Ensures(
        Res == Some(defense_in)
      )
    )
    val value : Option[Mining_Threat_Retreat_Supervisor.Defense_Command.Type] = Art.getValue(defense_in_Id) match {
      case Some(Mining_Threat_Retreat_Supervisor.Defense_Command_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port defense_in.  Expecting 'Mining_Threat_Retreat_Supervisor.Defense_Command_Payload' but received ${v}")
        None[Mining_Threat_Retreat_Supervisor.Defense_Command.Type]()
      case _ => None[Mining_Threat_Retreat_Supervisor.Defense_Command.Type]()
    }
    return value
  }
}
